window.addEventListener('click',async e=>{let t=e.target.closest('[data-parity="capture"]');if(!t)return;e.preventDefault();e.stopImmediatePropagation();let label=t.innerHTML,restoreHeaderMenu=window.MMGangHeader?.closeForCapture(t),restoreCommandMenu=window.MMCommandInterface?.closeForCapture(t);t.disabled=true;try{await document.fonts?.ready;const content=document.querySelector('.content');if(!window.htmlToImage)throw Error('Image export is not available.');const image=await htmlToImage.toJpeg(content,{quality:.85,pixelRatio:1.3,style:{margin:'0'},backgroundColor:document.documentElement.classList.contains('light')?'#ffffff':'#000000',filter:node=>!node.classList?.contains('mm-settings-menu')});let a=document.createElement('a'),name=(data.view==='campaign'?campaign()?.name:gang()?.name)||'언더하이브 코리아';a.download=new Date().toISOString().slice(0,19).replace(/[:T]/g,'_')+'_'+name.replace(/\s+/g,'_')+'-언더하이브_코리아.jpg';a.href=image;a.click()}catch(err){showModal('Screenshot failed',`<p>${esc(err.message)}</p>`,'Close',()=>true)}finally{if(t.isConnected){t.disabled=false;t.innerHTML=label}restoreHeaderMenu?.();restoreCommandMenu?.()}},true);
